	/*
     * @param	event CreateCreativeFileEvent
     */
    @EventHandler( payloadType=CreateCreativeFileEvent.class )
    public void handle( CreateCreativeFileEvent event) {
	    LOGGER.info("handling CreateCreativeFileEvent - " + event );
	    CreativeFile entity = new CreativeFile();
            entity.setCreativeFileId( event.getCreativeFileId() );
            entity.setUri( event.getUri() );
            entity.setFileSizeKB( event.getFileSizeKB() );
            entity.setMimeType( event.getMimeType() );
            entity.setChecksum( event.getChecksum() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCreativeFile( entity );
    }

    /*
     * @param	event UpdateCreativeFileEvent
     */
    @EventHandler( payloadType=UpdateCreativeFileEvent.class )
    public void handle( UpdateCreativeFileEvent event) {
    	LOGGER.info("handling UpdateCreativeFileEvent - " + event );
    	
	    CreativeFile entity = new CreativeFile();
            entity.setCreativeFileId( event.getCreativeFileId() );
            entity.setUri( event.getUri() );
            entity.setFileSizeKB( event.getFileSizeKB() );
            entity.setMimeType( event.getMimeType() );
            entity.setChecksum( event.getChecksum() );
            entity.setCreativeAsset( event.getCreativeAsset() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCreativeFile( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCreativeFile( entity );        
    }
    
